#include <bits/stdc++.h>
using namespace std;

// JSON value. t: 'o' object, 'a' array, 's' string, 'n' number (s = exact canonical form),
// 'b' bool (s = literal), 'z' null. Object members are sorted by key.
struct Val {
    char t = 'z';
    string s;
    vector<Val> a;
    vector<pair<string, Val>> o;
};

string S;
size_t p = 0;

void ws() { while (p < S.size() && (S[p] == ' ' || S[p] == '\t' || S[p] == '\n' || S[p] == '\r')) p++; }

void putUtf8(string &out, unsigned cp) {
    if (cp < 0x80) out += char(cp);
    else if (cp < 0x800) { out += char(0xC0 | cp >> 6); out += char(0x80 | (cp & 0x3F)); }
    else if (cp < 0x10000) { out += char(0xE0 | cp >> 12); out += char(0x80 | (cp >> 6 & 0x3F)); out += char(0x80 | (cp & 0x3F)); }
    else { out += char(0xF0 | cp >> 18); out += char(0x80 | (cp >> 12 & 0x3F)); out += char(0x80 | (cp >> 6 & 0x3F)); out += char(0x80 | (cp & 0x3F)); }
}

unsigned hex4() { unsigned v = stoul(S.substr(p, 4), nullptr, 16); p += 4; return v; }

string parseString() {
    p++; // opening quote
    string out;
    while (S[p] != '"') {
        char c = S[p++];
        if (c != '\\') { out += c; continue; }
        char e = S[p++];
        switch (e) {
            case 'b': out += '\b'; break;
            case 'f': out += '\f'; break;
            case 'n': out += '\n'; break;
            case 'r': out += '\r'; break;
            case 't': out += '\t'; break;
            case 'u': {
                unsigned cp = hex4();
                if (cp >= 0xD800 && cp < 0xDC00 && S[p] == '\\' && S[p + 1] == 'u') { // surrogate pair
                    p += 2;
                    cp = 0x10000 + ((cp - 0xD800) << 10) + (hex4() - 0xDC00);
                }
                putUtf8(out, cp);
                break;
            }
            default: out += e; // \" \\ \/
        }
    }
    p++;
    return out;
}

// Exact decimal value as sign + significant digits + exponent, so 1e-6 == 0.000001 and -0 == 0.
string canonicalNumber(const string &tok) {
    size_t i = 0;
    bool neg = tok[i] == '-';
    if (neg) i++;
    string digits;
    int scale = 0;
    while (i < tok.size() && isdigit((unsigned char)tok[i])) digits += tok[i++];
    if (i < tok.size() && tok[i] == '.') {
        i++;
        while (i < tok.size() && isdigit((unsigned char)tok[i])) { digits += tok[i++]; scale++; }
    }
    long long exp = 0;
    if (i < tok.size() && (tok[i] == 'e' || tok[i] == 'E')) exp = stoll(tok.substr(i + 1));
    size_t lead = digits.find_first_not_of('0');
    if (lead == string::npos) return "0";
    digits = digits.substr(lead);
    size_t last = digits.find_last_not_of('0');
    long long trailing = digits.size() - 1 - last;
    digits.resize(last + 1);
    return string(neg ? "-" : "") + digits + "e" + to_string(exp - scale + trailing);
}

Val parseValue() {
    ws();
    Val v;
    char c = S[p];
    if (c == '{') {
        v.t = 'o';
        p++;
        ws();
        if (S[p] == '}') { p++; return v; }
        while (true) {
            ws();
            string key = parseString();
            ws();
            p++; // :
            Val child = parseValue();
            v.o.emplace_back(move(key), move(child));
            ws();
            if (S[p++] == '}') break;
        }
        sort(v.o.begin(), v.o.end(), [](auto &x, auto &y) { return x.first < y.first; });
    } else if (c == '[') {
        v.t = 'a';
        p++;
        ws();
        if (S[p] == ']') { p++; return v; }
        while (true) {
            v.a.push_back(parseValue());
            ws();
            if (S[p++] == ']') break;
        }
    } else if (c == '"') {
        v.t = 's';
        v.s = parseString();
    } else if (c == 't') { v.t = 'b'; v.s = "true"; p += 4; }
    else if (c == 'f') { v.t = 'b'; v.s = "false"; p += 5; }
    else if (c == 'n') { v.t = 'z'; p += 4; }
    else {
        size_t start = p;
        while (p < S.size() && (isdigit((unsigned char)S[p]) || strchr("+-.eE", S[p]))) p++;
        v.t = 'n';
        v.s = canonicalNumber(S.substr(start, p - start));
    }
    return v;
}

// Structural equality: same type, ordered arrays, same key sets, exact numbers.
bool equal(const Val &x, const Val &y) {
    if (x.t != y.t) return false;
    if (x.t == 'o') {
        if (x.o.size() != y.o.size()) return false;
        for (size_t i = 0; i < x.o.size(); i++)
            if (x.o[i].first != y.o[i].first || !equal(x.o[i].second, y.o[i].second)) return false;
        return true;
    }
    if (x.t == 'a') {
        if (x.a.size() != y.a.size()) return false;
        for (size_t i = 0; i < x.a.size(); i++)
            if (!equal(x.a[i], y.a[i])) return false;
        return true;
    }
    return x.s == y.s;
}

string quote(const string &s) {
    string out = "\"";
    for (unsigned char c : s) {
        if (c == '"') out += "\\\"";
        else if (c == '\\') out += "\\\\";
        else if (c == '\n') out += "\\n";
        else if (c == '\r') out += "\\r";
        else if (c == '\t') out += "\\t";
        else if (c == '\b') out += "\\b";
        else if (c == '\f') out += "\\f";
        else if (c < 0x20) { char buf[8]; snprintf(buf, sizeof buf, "\\u%04x", c); out += buf; }
        else out += char(c);
    }
    return out + "\"";
}

int main() {
    S.assign(istreambuf_iterator<char>(cin), istreambuf_iterator<char>());
    Val a = parseValue(), b = parseValue();
    map<string, const Val *> left, right;
    for (auto &[k, v] : a.o) left[k] = &v;
    for (auto &[k, v] : b.o) right[k] = &v;
    set<string> keys; // UTF-8 byte order == code point order
    for (auto &[k, v] : left) {
        auto it = right.find(k);
        if (it == right.end() || !equal(*v, *it->second)) keys.insert(k);
    }
    for (auto &[k, v] : right)
        if (!left.count(k)) keys.insert(k);
    string out = "[";
    for (auto &k : keys) {
        if (out.size() > 1) out += ", ";
        out += quote(k);
    }
    cout << out << "]\n";
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    // JSON value. t: 'o' object, 'a' array, 's' string, 'n' number (s = exact canonical form),
    // 'b' bool (s = literal), 'z' null.
    static class Val {
        char t = 'z';
        String s = "";
        List<Val> a;
        HashMap<String, Val> o;
    }

    static String S;
    static int p = 0;

    static void ws() {
        while (p < S.length()) {
            char c = S.charAt(p);
            if (c != ' ' && c != '\t' && c != '\n' && c != '\r') return;
            p++;
        }
    }

    static String parseString() {
        p++; // opening quote
        StringBuilder out = new StringBuilder();
        while (S.charAt(p) != '"') {
            char c = S.charAt(p++);
            if (c != '\\') { out.append(c); continue; }
            char e = S.charAt(p++);
            switch (e) {
                case 'b': out.append('\b'); break;
                case 'f': out.append('\f'); break;
                case 'n': out.append('\n'); break;
                case 'r': out.append('\r'); break;
                case 't': out.append('\t'); break;
                case 'u': out.append((char) Integer.parseInt(S.substring(p, p + 4), 16)); p += 4; break; // UTF-16 unit
                default: out.append(e); // \" \\ \/
            }
        }
        p++;
        return out.toString();
    }

    // Exact decimal value as sign + significant digits + exponent, so 1e-6 == 0.000001 and -0 == 0.
    static String canonicalNumber(String tok) {
        int i = 0;
        boolean neg = tok.charAt(0) == '-';
        if (neg) i++;
        StringBuilder digits = new StringBuilder();
        int scale = 0;
        while (i < tok.length() && Character.isDigit(tok.charAt(i))) digits.append(tok.charAt(i++));
        if (i < tok.length() && tok.charAt(i) == '.') {
            i++;
            while (i < tok.length() && Character.isDigit(tok.charAt(i))) { digits.append(tok.charAt(i++)); scale++; }
        }
        long exp = 0;
        if (i < tok.length() && (tok.charAt(i) == 'e' || tok.charAt(i) == 'E')) {
            String e = tok.substring(i + 1);
            exp = Long.parseLong(e.startsWith("+") ? e.substring(1) : e);
        }
        int lead = 0;
        while (lead < digits.length() && digits.charAt(lead) == '0') lead++;
        if (lead == digits.length()) return "0";
        int last = digits.length() - 1;
        while (digits.charAt(last) == '0') last--;
        long trailing = digits.length() - 1 - last;
        return (neg ? "-" : "") + digits.substring(lead, last + 1) + "e" + (exp - scale + trailing);
    }

    static Val parseValue() {
        ws();
        Val v = new Val();
        char c = S.charAt(p);
        if (c == '{') {
            v.t = 'o';
            v.o = new HashMap<>();
            p++;
            ws();
            if (S.charAt(p) == '}') { p++; return v; }
            while (true) {
                ws();
                String key = parseString();
                ws();
                p++; // :
                v.o.put(key, parseValue());
                ws();
                if (S.charAt(p++) == '}') break;
            }
        } else if (c == '[') {
            v.t = 'a';
            v.a = new ArrayList<>();
            p++;
            ws();
            if (S.charAt(p) == ']') { p++; return v; }
            while (true) {
                v.a.add(parseValue());
                ws();
                if (S.charAt(p++) == ']') break;
            }
        } else if (c == '"') {
            v.t = 's';
            v.s = parseString();
        } else if (c == 't') { v.t = 'b'; v.s = "true"; p += 4; }
        else if (c == 'f') { v.t = 'b'; v.s = "false"; p += 5; }
        else if (c == 'n') { v.t = 'z'; p += 4; }
        else {
            int start = p;
            while (p < S.length() && (Character.isDigit(S.charAt(p)) || "+-.eE".indexOf(S.charAt(p)) >= 0)) p++;
            v.t = 'n';
            v.s = canonicalNumber(S.substring(start, p));
        }
        return v;
    }

    // Structural equality: same type, ordered arrays, same key sets, exact numbers.
    static boolean equal(Val x, Val y) {
        if (x.t != y.t) return false;
        if (x.t == 'o') {
            if (!x.o.keySet().equals(y.o.keySet())) return false;
            for (Map.Entry<String, Val> e : x.o.entrySet())
                if (!equal(e.getValue(), y.o.get(e.getKey()))) return false;
            return true;
        }
        if (x.t == 'a') {
            if (x.a.size() != y.a.size()) return false;
            for (int i = 0; i < x.a.size(); i++)
                if (!equal(x.a.get(i), y.a.get(i))) return false;
            return true;
        }
        return x.s.equals(y.s);
    }

    // Unicode code point order (String.compareTo compares UTF-16 units instead).
    static int byCodePoint(String x, String y) {
        int i = 0, j = 0;
        while (i < x.length() && j < y.length()) {
            int a = x.codePointAt(i), b = y.codePointAt(j);
            if (a != b) return Integer.compare(a, b);
            i += Character.charCount(a);
            j += Character.charCount(b);
        }
        return Integer.compare(x.length() - i, y.length() - j);
    }

    static void quote(String s, StringBuilder out) {
        out.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') out.append("\\\"");
            else if (c == '\\') out.append("\\\\");
            else if (c == '\n') out.append("\\n");
            else if (c == '\r') out.append("\\r");
            else if (c == '\t') out.append("\\t");
            else if (c == '\b') out.append("\\b");
            else if (c == '\f') out.append("\\f");
            else if (c < 0x20) out.append(String.format("\\u%04x", (int) c));
            else out.append(c);
        }
        out.append('"');
    }

    public static void main(String[] args) throws IOException {
        S = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        Val a = parseValue(), b = parseValue();
        List<String> keys = new ArrayList<>();
        for (Map.Entry<String, Val> e : a.o.entrySet()) {
            Val other = b.o.get(e.getKey());
            if (other == null || !equal(e.getValue(), other)) keys.add(e.getKey());
        }
        for (String k : b.o.keySet()) if (!a.o.containsKey(k)) keys.add(k);
        keys.sort(Main::byCodePoint);
        StringBuilder out = new StringBuilder("[");
        for (int i = 0; i < keys.size(); i++) {
            if (i > 0) out.append(", ");
            quote(keys.get(i), out);
        }
        out.append("]\n");
        PrintStream ps = new PrintStream(new FileOutputStream(FileDescriptor.out), false, StandardCharsets.UTF_8);
        ps.print(out);
        ps.flush();
    }
}

package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

// canonical writes an exact decimal as sign + significant digits + exponent,
// so 1e-6 == 0.000001 and -0 == 0.
func canonical(tok string) string {
	neg := strings.HasPrefix(tok, "-")
	tok = strings.TrimPrefix(tok, "-")
	mant, expPart, _ := strings.Cut(strings.ToLower(tok), "e")
	exp := int64(0)
	if expPart != "" {
		exp, _ = strconv.ParseInt(expPart, 10, 64)
	}
	intPart, frac, _ := strings.Cut(mant, ".")
	digits := strings.TrimLeft(intPart+frac, "0")
	if digits == "" {
		return "0"
	}
	trimmed := strings.TrimRight(digits, "0")
	exp += int64(len(digits)-len(trimmed)) - int64(len(frac))
	sign := ""
	if neg {
		sign = "-"
	}
	return sign + trimmed + "e" + strconv.FormatInt(exp, 10)
}

// equal is structural equality: same type, ordered arrays, same key sets, exact numbers.
func equal(x, y any) bool {
	switch a := x.(type) {
	case map[string]any:
		b, ok := y.(map[string]any)
		if !ok || len(a) != len(b) {
			return false
		}
		for k, v := range a {
			w, ok := b[k]
			if !ok || !equal(v, w) {
				return false
			}
		}
		return true
	case []any:
		b, ok := y.([]any)
		if !ok || len(a) != len(b) {
			return false
		}
		for i := range a {
			if !equal(a[i], b[i]) {
				return false
			}
		}
		return true
	case json.Number:
		b, ok := y.(json.Number)
		return ok && canonical(string(a)) == canonical(string(b))
	case string:
		b, ok := y.(string)
		return ok && a == b
	case bool:
		b, ok := y.(bool)
		return ok && a == b
	default: // null
		return y == nil
	}
}

func quote(s string, w *bufio.Writer) {
	w.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"':
			w.WriteString(`\"`)
		case c == '\\':
			w.WriteString(`\\`)
		case c == '\n':
			w.WriteString(`\n`)
		case c == '\r':
			w.WriteString(`\r`)
		case c == '\t':
			w.WriteString(`\t`)
		case c == '\b':
			w.WriteString(`\b`)
		case c == '\f':
			w.WriteString(`\f`)
		case c < 0x20:
			fmt.Fprintf(w, `\u%04x`, c)
		default:
			w.WriteByte(c)
		}
	}
	w.WriteByte('"')
}

func main() {
	dec := json.NewDecoder(bufio.NewReader(os.Stdin))
	dec.UseNumber()
	var a, b map[string]any
	if err := dec.Decode(&a); err != nil {
		panic(err)
	}
	if err := dec.Decode(&b); err != nil {
		panic(err)
	}
	var keys []string
	for k, v := range a {
		w, ok := b[k]
		if !ok || !equal(v, w) {
			keys = append(keys, k)
		}
	}
	for k := range b {
		if _, ok := a[k]; !ok {
			keys = append(keys, k)
		}
	}
	sort.Strings(keys) // UTF-8 byte order == code point order
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteByte('[')
	for i, k := range keys {
		if i > 0 {
			w.WriteString(", ")
		}
		quote(k, w)
	}
	w.WriteString("]\n")
}
